<?php
namespace App\Filament\Admin\Resources\Renewals\Pages;use App\Filament\Admin\Concerns\ServiceValidation;use App\Filament\Admin\Resources\Renewals\RenewalResource;use App\Models\Policy;use Filament\Actions\Action;use Filament\Forms\Components\Select;use App\Filament\Shared\Pages\RecordDetailPage;final class ViewRenewal extends RecordDetailPage{protected static string $resource=RenewalResource::class;protected function getHeaderActions():array{return[/* P6 2026-09-29: gated like POST renewals/{r}/quote|complete (renewals.manage) + own record (docs/spec/PORTAL_WRITE_RULES.md) */Action::make('quote')->label(fn()=>\App\Application\WebExperiences\PortalScope::panel()!==null?__('broker_portal_service.renewalQuote.label'):'Quote')->icon('lucide-calculator')->authorize(fn()=>\App\Application\WebExperiences\PortalScope::allowsWrite('renewals.manage',$this->record))->visible(fn()=>in_array($this->record->status,['DUE','CONTACTED'],true))->action(function(){if(ServiceValidation::run(fn()=>app(\App\Application\Policies\RenewalService::class)->createQuote($this->record,auth()->user()))===null)return;}),Action::make('complete')->label(fn()=>\App\Application\WebExperiences\PortalScope::panel()!==null?__('broker_portal_service.renewalComplete.label'):'Link successor')->authorize(fn()=>\App\Application\WebExperiences\PortalScope::allowsWrite('renewals.manage',$this->record))->icon('lucide-link')->color('success')->visible(fn()=>$this->record->status==='QUOTED')->schema([Select::make('successor_policy_id')->options(fn()=>Policy::where(['tenant_id'=>$this->record->tenant_id,'previous_policy_id'=>$this->record->policy_id,'status'=>'ACTIVE'])->pluck('policy_number','id'))->required()->searchable()])->action(function(array$data){if(ServiceValidation::run(fn()=>app(\App\Application\Policies\RenewalService::class)->complete($this->record,Policy::where('tenant_id',$this->record->tenant_id)->findOrFail($data['successor_policy_id'])))===null)return;})];}}
